// generated by ledger -- do not edit; run `ledger product`
// One client for every target. The web, desktop and mobile builds differ only in
// baseUrl and auth mode, which is why there is no second implementation here.

import type { LedgerJob, Problem, RunRequest, RunResult } from "./types";

/** How this build reaches the API. The values come from ../targets/<name>.json. */
export type Auth = { mode: "session" } | { mode: "loopback_token"; token: string };

export interface ClientOptions {
  /** API_BASE for this target. There is no default: Ledger does not invent a hostname. */
  baseUrl: string;
  auth: Auth;
  fetchImpl?: typeof fetch;
}

export class ApiError extends Error {
  readonly status: number;
  readonly problem: Problem | null;

  constructor(status: number, problem: Problem | null) {
    super(problem && problem.title ? problem.title : "HTTP " + status);
    this.name = "ApiError";
    this.status = status;
    this.problem = problem;
  }
}

export class VeritradeClient {
  private readonly baseUrl: string;
  private readonly auth: Auth;
  private readonly fetchImpl: typeof fetch;

  constructor(options: ClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/+$/, "");
    this.auth = options.auth;
    this.fetchImpl = options.fetchImpl ?? globalThis.fetch.bind(globalThis);
  }

  async health(): Promise<{ status: string }> {
    return this.send<{ status: string }>("GET", "/healthz");
  }

  async createRun(body: RunRequest): Promise<LedgerJob> {
    return this.send<LedgerJob>("POST", "/runs", body);
  }

  async getRun(runId: string): Promise<LedgerJob> {
    return this.send<LedgerJob>("GET", "/runs/" + encodeURIComponent(runId));
  }

  async getResult(runId: string): Promise<RunResult> {
    return this.send<RunResult>("GET", "/runs/" + encodeURIComponent(runId) + "/result");
  }

  // No `events:` type is declared in the product block, so no event stream is
  // generated. Live progress needs that type before it can be typed.

  private async send<T>(method: string, path: string, body?: unknown): Promise<T> {
    const headers: Record<string, string> = { accept: "application/json" };
    if (body !== undefined) headers["content-type"] = "application/json";
    if (this.auth.mode === "loopback_token") {
      headers["authorization"] = "Bearer " + this.auth.token;
    }
    const response = await this.fetchImpl(this.baseUrl + path, {
      method,
      headers,
      credentials: this.auth.mode === "session" ? "include" : "omit",
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (!response.ok) {
      let problem: Problem | null = null;
      try {
        problem = (await response.json()) as Problem;
      } catch {
        problem = null;
      }
      throw new ApiError(response.status, problem);
    }
    if (response.status === 204) return undefined as unknown as T;
    return (await response.json()) as T;
  }
}
